let publicModelIndexPromise,publicAuditEpoch=0,publicAuditCurrent=null;
function publicAuditPage(){return journeyPage(3,'Check the requirements against your actual record.',`<p class="journey-lede">Public sources. Exact course identities. Clear remaining conditions.</p><p>These checks use completed coursework only. Planned courses and unconfirmed transfer credit do not count as earned. Many programs retain source conditions without automatic checks. Every unmodeled policy remains visible and can be recorded as checked against the source.</p><section class="degree-optimizer"><div class="form-grid"><label>Find a program<input id="audit-program-search" type="search" maxlength="150" placeholder="Informatics, electrical engineering…"></label><label>College<select id="audit-college"><option value="">All loaded colleges</option>${ProgramCatalog.institutions.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></label><label>Exact program<select id="audit-program"><option value="">Loading source models…</option></select></label><label>Scope<select id="audit-phase"><option value="all">Admission and completion</option><option value="admission">Admission preparation</option><option value="degree">Degree completion</option></select></label></div><p class="quiet-note" id="audit-model-coverage"></p><label><input type="checkbox" id="audit-include-equivalents"> Also show provisional matches from exact public transfer-guide rows for the term I took each class. These are not awarded credits.</label><button class="btn primary" id="run-public-audit">Check my completed record →</button><div id="public-audit-results" aria-live="polite"></div></section><a class="journey-secondary" href="#degrees">Connected degree planning →</a>`,'roadmap')}
async function getPublicModelIndex(){return publicModelIndexPromise||=fetch('public-models/index.json').then(r=>{if(!r.ok)throw Error('Source-model index unavailable.');return r.json()}).catch(e=>{publicModelIndexPromise=null;throw e})}
function sourceTextForReader(value){if(typeof value==='string')return value;if(Array.isArray(value))return value.map(sourceTextForReader).join('\n\n');if(value&&typeof value==='object')return Object.entries(value).map(([k,v])=>k+'\n'+sourceTextForReader(v)).join('\n\n');return ''}
async function runPublicAudit(){const target=document.querySelector('#public-audit-results'),select=document.querySelector('#audit-program');if(!target||!select)return;const id=select.value,token=++publicAuditEpoch;target.innerHTML='<p role="status">Checking published source rules against saved completed courses…</p>';try{const index=await getPublicModelIndex(),entry=index.programs.find(p=>p.id===id);if(!entry)throw Error('Choose an exact source program first.');const response=await fetch('public-models/'+encodeURIComponent(entry.file));if(!response.ok)throw Error('This source model could not load.');const model=await response.json();if(token!==publicAuditEpoch||!target.isConnected)return;let mapped={records:[],evidence:[]};if(document.querySelector('#audit-include-equivalents').checked){transferEvidencePromise||=publicSnapshot('transfer-evidence.json').catch(e=>{transferEvidencePromise=null;throw e});const transfer=await transferEvidencePromise;if(token!==publicAuditEpoch||!target.isConnected)return;mapped=PublicTransferChecks.equivalentRecords(state.courses||[],transfer.records,model.institution)}const phase=document.querySelector('#audit-phase').value,result=PublicAudit.evaluate(model,[...(state.courses||[]),...mapped.records],{phase,reviews:state.publicAuditReviews?.[id]||{}});publicAuditCurrent={model,result,entry,mapped};renderPublicAudit(target)}catch(e){if(target.isConnected&&token===publicAuditEpoch)target.innerHTML=`<p role="alert">${esc(e.message)}</p>`}}
function renderPublicAudit(target){const{model,result,entry,mapped}=publicAuditCurrent,count=result.counts,labels={'satisfied':'Matched in completed record','remaining':'Remaining','needs-review':'Needs source / record review','checked-by-you':'Checked by you','not-applicable':'Marked not applicable by you','source-equivalent':'Published equivalent — applicability review'};target.innerHTML=`<span class="eyebrow">SOURCE SNAPSHOT · ${esc(model.checked)}</span><h2>${esc(model.title)} · ${esc(model.institution)}</h2><p>${esc(entry.credential||'')}</p><p>${entry.typedRules} structured source checks; ${entry.sourceClauses} retained source conditions. Unmodeled source conditions still require review.</p><div class="audit-summary"><span><strong>${count.satisfied||0}</strong> matched checks</span><span><strong>${count.remaining||0}</strong> remaining checks</span><span><strong>${count['needs-review']||0}</strong> unresolved checks</span><span><strong>${count['checked-by-you']||0}</strong> checked by you</span></div><p>${result.earnedCredits} ${esc(model.units.toLowerCase())} credits in exact-institution completed records. ${result.recordGpa===null?'Numeric GPA not available for this group.':'Saved-record numeric GPA: '+result.recordGpa.toFixed(3)+'.'} External credit is not silently reclassified.</p>${result.unknownUnits?`<p class="plan-trust-alert">${result.unknownUnits} record(s) omitted because their credit system is unknown. Review them before relying on these checks.</p>`:''}${result.duplicates.length?`<p class="plan-trust-alert">Repeat-course policy needs review for ${result.duplicates.map(esc).join(', ')}. Attempts are not simply added together.</p>`:''}${mapped?.evidence.length?`<details><summary>${mapped.evidence.length} provisional public equivalency matches</summary>${mapped.evidence.map(e=>`<p>${esc(e.from)} → ${esc(e.to)} · ${esc(e.term)}<br><a href="${esc(e.source)}" target="_blank" rel="noopener">Published guide ↗</a> · ${esc(e.scope)}</p>`).join('')}</details>`:''}<p class="plan-trust-alert">This is a source-based check, not a degree award or full automatic eligibility decision. A matched course clause does not resolve its adjacent policy, residency, elective cap or catalog-year exception.</p><a class="journey-secondary" href="${esc(model.source)}" target="_blank" rel="noopener">Check the published source ↗</a><details><summary>Full retained source context</summary><div class="uw-source-text" tabindex="0">${esc(sourceTextForReader(model.sourceText))}</div></details><div class="public-audit-checks">${result.checks.map((r,i)=>`<article class="degree-goal audit-${r.status}"><span class="eyebrow">${esc(r.phase)} · ${esc(labels[r.status])}</span><h3>${esc(r.type.replaceAll('-',' '))}</h3><div class="catalog-source-excerpt">${esc(r.sourceText)}</div><p>${esc(r.detail)}</p>${r.alternatives?`<details><summary>Whole-sequence alternatives</summary>${r.alternatives.map(a=>`<p>${esc(a.status)}: ${esc(a.detail)}</p>`).join('')}</details>`:''}${(['needs-review','checked-by-you','not-applicable'].includes(r.status)||r.studentChecked)&&!r.alternatives?`<details><summary>Record your own source check</summary><p>This records your interpretation with a note. It does not change the source or override a separate numeric/course check.</p><label>Decision<select data-audit-decision="${i}"><option value="">Keep unresolved</option><option value="met" ${state.publicAuditReviews?.[model.id]?.[r.id]?.status==='met'?'selected':''}>I checked that this condition is met</option><option value="not-met" ${state.publicAuditReviews?.[model.id]?.[r.id]?.status==='not-met'?'selected':''}>This condition remains unmet</option><option value="not-applicable" ${state.publicAuditReviews?.[model.id]?.[r.id]?.status==='not-applicable'?'selected':''}>Not applicable to my source-defined route</option></select></label><label>What did you verify? Include applicable year/route.<textarea data-audit-note="${i}" maxlength="500" rows="3">${esc(state.publicAuditReviews?.[model.id]?.[r.id]?.note||'')}</textarea></label><button class="btn" data-save-audit-review="${i}">Save my source check</button></details>`:''}</article>`).join('')}</div><p class="quiet-note">No private institutional connection or approval is required. User checks are separate from computed results. Unpublished rules/data remain unresolved.</p>`;target.querySelectorAll('[data-save-audit-review]').forEach(b=>b.onclick=()=>{const i=+b.dataset.saveAuditReview,r=result.checks[i],status=target.querySelector('[data-audit-decision="'+i+'"]').value,note=target.querySelector('[data-audit-note="'+i+'"]').value.trim();state.publicAuditReviews||={};state.publicAuditReviews[model.id]||={};if(!status)delete state.publicAuditReviews[model.id][r.id];else{if(!note)return toast('Add what you checked before saving a decision.');state.publicAuditReviews[model.id][r.id]={status,note,checkedAt:new Date().toISOString(),source:model.source}}save();runPublicAudit()})}
async function bindPublicAudits(){const select=document.querySelector('#audit-program');if(!select)return;try{const data=await getPublicModelIndex();if(!select.isConnected)return;document.querySelector('#audit-model-coverage').textContent=data.programs.length+' source snapshots; '+data.programs.filter(p=>p.typedRules>0).length+' contain structured course, credit or grade rules. The remaining snapshots require source interpretation.';const search=document.querySelector('#audit-program-search'),college=document.querySelector('#audit-college'),draw=()=>{const old=select.value||state.profile?.primaryProgramId||'',rows=data.programs.filter(p=>(!college.value||p.institution===college.value)&&[p.title,p.credential,p.institution].join(' ').toLowerCase().includes(search.value.toLowerCase()));select.innerHTML=rows.map(p=>`<option value="${esc(p.id)}" ${p.id===old?'selected':''}>${esc(p.title)} · ${esc(p.institution)} · ${esc(p.credential||'Credential in source')} · ${p.typedRules} source checks</option>`).join('');if(!rows.length)select.innerHTML='<option value="">No matching source models</option>'};const invalidate=()=>{publicAuditEpoch++;publicAuditCurrent=null;document.querySelector('#public-audit-results').textContent='Choose Check my completed record to refresh these results.'};search.oninput=()=>{draw();invalidate()};college.onchange=()=>{draw();invalidate()};select.onchange=invalidate;draw();document.querySelector('#run-public-audit').onclick=runPublicAudit;document.querySelector('#audit-phase').onchange=()=>{if(publicAuditCurrent)runPublicAudit()}}catch(e){if(select.isConnected)document.querySelector('#public-audit-results').textContent=e.message}}
function installPublicAudits(){const oldBind=bind;bind=()=>{oldBind();bindPublicAudits()};const oldDegrees=degreePlanner;degreePlanner=()=>oldDegrees()+`<section class="degree-summary"><h2>Check the published requirements</h2><p>Compare completed classes with source-backed rules and record unresolved policy checks.</p><a class="btn primary" href="#source-audit">Open public-source checks →</a></section>`;const oldRoadmap=roadmap;roadmap=()=>oldRoadmap()+`<div class="degree-summary"><a class="btn" href="#source-audit">Check source requirements against my record →</a></div>`}
